"""Legacy-compatible CRMScript numeric division."""

from __future__ import annotations

import math
from typing import Union

NumericOperand = Union[int, float, str, None]


def _coerce_number(value: NumericOperand) -> float:
    """Coerce a supported operand using legacy numeric-context semantics."""
    if value is None or value == "":
        return 0.0

    try:
        return float(value)
    except OverflowError:
        # Preserve a floating-point result for valid numbers beyond float range.
        return -math.inf if value < 0 else math.inf


def safe_div(a: NumericOperand, b: NumericOperand) -> tuple[float, list[str]]:
    """Divide with the legacy zero-divisor result and audit behavior."""
    divisor = _coerce_number(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    dividend = _coerce_number(a)
    return dividend / divisor, []
